Core Clinical & EMR Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_clinical_emr_service, "Core Clinical & EMR Service") {
    Component(PatientRecordManager, "Patient Record Manager", "Java / Spring Boot", "Manages patient admissions and electronic medical records (EMR).")
    Component(AuthorizationPolicyEngine, "Authorization & Policy Engine", "Java / Spring Boot", "Evaluates fine-grained access policies for requests.")
    Component(AuditLoggingInterceptor, "Audit Logging Interceptor", "Java / Spring Boot", "Intercepts requests and appends audit events for HIPAA/GDPR compliance.")
    Component(FHIRInteroperabilityAdapter, "FHIR Interoperability Adapter", "Java / Spring Boot / HAPI FHIR", "Exchanges standardized clinical data with external lab and imaging systems.")
    Component(CryptoKeyManagementFacade, "Crypto & Key Management Facade", "Java / Spring Boot / Secure Hardware Interface", "Manages envelope encryption keys using an On-Premises HSM.")
}

Rel(AuthorizationPolicyEngine, PatientRecordManager, "Evaluates fine-grained access", "In-process calls")

@enduml

PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the PostgreSQL container

System_Ext(OnPrisHSM, "On-Premises HSM", "Cryptographic key management")
System_Ext(ImmutableAuditLog, "Immutable Audit Log", "External audit storage")

Container_Boundary(PostgreSQL, "PostgreSQL") {
    Component(RowLevelSecurityEncryptionManager, "Row-Level Security & Encryption Manager", "PostgreSQL RLS & Transparent Data Encryption", "Manages row-level data segregation and cryptographic encryption at rest.")
    Component(pgauditComplianceModule, "pgaudit Compliance Module", "PostgreSQL Extension (pgaudit)", "Captures immutable DDL and DML audit trails for compliance.")
}

Rel(RowLevelSecurityEncryptionManager, OnPrisHSM, "Requests cryptographic keys", "PKCS#11 / gRPC over TLS")
Rel(pgauditComplianceModule, ImmutableAuditLog, "Streams audit records", "Syslog / TLS")

@enduml

Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Redis container

Person(Scheduling_Billing_Service, "Scheduling & Billing Service", "External service interacting with Redis")

Container_Boundary(Redis, "Redis") {
    Component(Core_In_Memory_Data_Store, "Core In-Memory Data Store", "Redis OSS / Enterprise", "Caches encrypted session/lookup data and provides high-throughput in-memory storage.")
    Component(Lock_Coordination_Engine, "Lock Coordination Engine", "Redlock Engine", "Acquires scheduling mutex locks for conflict-free appointment management.")
    Component(Replication_Persistence_Controller, "Replication & Persistence Controller", "Redis Sentinel, AOF (fsync everysec), and RDB", "Ensures automated failover under 3 seconds and balances data durability with performance.")
}

Rel(Scheduling_Billing_Service, Core_In_Memory_Data_Store, "Caches encrypted session/lookup data", "RESP/TLS 1.3")
Rel(Scheduling_Billing_Service, Lock_Coordination_Engine, "Acquires scheduling mutex locks", "RESP/TLS 1.3")

@enduml
